/* MiniBit live 3D viewer (software renderer). Call window.__minibitViewer() once the markup exists; it returns a stop function. */
window.__minibitViewer=function(){
const D = {"shell": "", "lid": "", "bolts": "", "pocketZ0": 0.8, "pocketZ1": 21.900000000000002, "backZ": 23.900000000000002, "cy": 6.149999618530273, "ringH": 6.0, "outW": 52.0, "outH": 44.0};
function dec(b64){const bin=atob(b64);const u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);return new Int16Array(u.buffer).map?Float32Array.from(new Int16Array(u.buffer),v=>v/100):null;}
function mk(b64,col){const p=dec(b64);const n=p.length/9;const nm=new Float32Array(n*3);
 for(let i=0;i<n;i++){const o=i*9;const ax=p[o+3]-p[o],ay=p[o+4]-p[o+1],az=p[o+5]-p[o+2];
  const bx=p[o+6]-p[o],by=p[o+7]-p[o+1],bz=p[o+8]-p[o+2];
  let nx=ay*bz-az*by,ny=az*bx-ax*bz,nz=ax*by-ay*bx;const l=Math.hypot(nx,ny,nz)||1;nm[i*3]=nx/l;nm[i*3+1]=ny/l;nm[i*3+2]=nz/l;}
 return {p,nm,n,col};}
const shell=mk(D.shell,[62,62,70]), lid=mk(D.lid,[50,50,58]), bolts=mk(D.bolts,[250,225,40]);

// mock board (landscape, z from pocketZ0+0.1, 15 mm deep) built as quads -> triangles
const bz0=D.pocketZ0+0.1,bz1=bz0+15.0,bw=45.2/2,bh=37.6/2;
function quad(a,b,c,d){return [...a,...b,...c,...a,...c,...d];}
function boardTris(){
 const t=[];const P=(x,y,z)=>[x,y,z];
 // back, left, right, top, bottom, front (winding so normals point outward)
 t.push(...quad(P(-bw,-bh,bz1),P(-bw,bh,bz1),P(bw,bh,bz1),P(bw,-bh,bz1)));      // back (+z)
 t.push(...quad(P(-bw,-bh,bz0),P(-bw,bh,bz0),P(-bw,bh,bz1),P(-bw,-bh,bz1)));    // left
 t.push(...quad(P(bw,-bh,bz1),P(bw,bh,bz1),P(bw,bh,bz0),P(bw,-bh,bz0)));        // right
 t.push(...quad(P(-bw,bh,bz1),P(-bw,bh,bz0),P(bw,bh,bz0),P(bw,bh,bz1)));        // top
 t.push(...quad(P(-bw,-bh,bz0),P(-bw,-bh,bz1),P(bw,-bh,bz1),P(bw,-bh,bz0)));    // bottom
 t.push(...quad(P(bw,-bh,bz0),P(bw,bh,bz0),P(-bw,bh,bz0),P(-bw,-bh,bz0)));      // front (-z)
 return t;}
const board=(function(){const p=Float32Array.from(boardTris());const n=p.length/9;const nm=new Float32Array(n*3);
 for(let i=0;i<n;i++){const o=i*9;const ax=p[o+3]-p[o],ay=p[o+4]-p[o+1],az=p[o+5]-p[o+2];
  const bx=p[o+6]-p[o],by=p[o+7]-p[o+1],bz=p[o+8]-p[o+2];let nx=ay*bz-az*by,ny=az*bx-ax*bz,nz=ax*by-ay*bx;const l=Math.hypot(nx,ny,nz)||1;nm[i*3]=nx/l;nm[i*3+1]=ny/l;nm[i*3+2]=nz/l;}
 return {p,nm,n,col:[48,48,56]};})();
// battery (502030, 30.5 x 20 x 5) lying behind the board
function boxTris(x0,x1,y0,y1,z0,z1){const P=(x,y,z)=>[x,y,z];const t=[];
 t.push(...quad(P(x0,y0,z1),P(x0,y1,z1),P(x1,y1,z1),P(x1,y0,z1)));t.push(...quad(P(x0,y0,z0),P(x0,y1,z0),P(x0,y1,z1),P(x0,y0,z1)));
 t.push(...quad(P(x1,y0,z1),P(x1,y1,z1),P(x1,y1,z0),P(x1,y0,z0)));t.push(...quad(P(x0,y1,z1),P(x0,y1,z0),P(x1,y1,z0),P(x1,y1,z1)));
 t.push(...quad(P(x0,y0,z0),P(x0,y0,z1),P(x1,y0,z1),P(x1,y0,z0)));t.push(...quad(P(x1,y0,z0),P(x1,y1,z0),P(x0,y1,z0),P(x0,y0,z0)));return t;}
function mkMesh(arr,col){const p=Float32Array.from(arr);const n=p.length/9;const nm=new Float32Array(n*3);
 for(let i=0;i<n;i++){const o=i*9;const ax=p[o+3]-p[o],ay=p[o+4]-p[o+1],az=p[o+5]-p[o+2];const bx=p[o+6]-p[o],by=p[o+7]-p[o+1],bz=p[o+8]-p[o+2];
  let nx=ay*bz-az*by,ny=az*bx-ax*bz,nz=ax*by-ay*bx;const l=Math.hypot(nx,ny,nz)||1;nm[i*3]=nx/l;nm[i*3+1]=ny/l;nm[i*3+2]=nz/l;}return {p,nm,n,col};}
const batt=mkMesh(boxTris(-15.25,15.25,-10,10,bz1+0.4,bz1+0.4+5.0),[200,205,215]);
// screen + eyes as thin quads just in front of the board front face
function rect(cx,cy,w,h,z){const x0=cx-w/2,x1=cx+w/2,y0=cy-h/2,y1=cy+h/2;
 return [x1,y0,z, x1,y1,z, x0,y1,z, x1,y0,z, x0,y1,z, x0,y0,z];}
function mkFlat(arr,col){const p=Float32Array.from(arr);const n=p.length/9;const nm=new Float32Array(n*3);for(let i=0;i<n;i++){nm[i*3+2]=-1;}return {p,nm,n,col};}
const screen=mkFlat(rect(0,0,34.94,28.7,bz0-0.15),[10,10,18]);
function pill(cx,cy,w,h,z){const r=w/2,N=14,pts=[];
 for(let i=0;i<=N;i++){const a=Math.PI*i/N;pts.push([cx+r*Math.cos(a),cy+h/2-r+r*Math.sin(a)]);}
 for(let i=0;i<=N;i++){const a=Math.PI+Math.PI*i/N;pts.push([cx+r*Math.cos(a),cy-h/2+r+r*Math.sin(a)]);}
 const t=[];for(let i=0;i<pts.length;i++){const a=pts[i],b=pts[(i+1)%pts.length];t.push(cx,cy,z,a[0],a[1],z,b[0],b[1],z);}return t;}
const glow=mkFlat([...pill(-6,0,5.0,10.4,bz0-0.2),...pill(6,0,5.0,10.4,bz0-0.2)],[18,62,82]);
const eyes=mkFlat([...pill(-6,0,3.2,8.6,bz0-0.3),...pill(6,0,3.2,8.6,bz0-0.3)],[70,230,255]);
eyes.emissive=true;

const cv=document.getElementById('cv'),ctx=cv.getContext('2d');
let yaw=-0.55,pitch=0.30,zoom=1,drag=false,lx=0,ly=0;
const center=[0,D.cy,D.backZ/2];
function view(name){const V={front:[0,0],back:[Math.PI,0],left:[-Math.PI/2,0],right:[Math.PI/2,0],top:[0,Math.PI/2*0.98],bottom:[0,-Math.PI/2*0.98],iso:[-0.55,0.30]};
 [yaw,pitch]=V[name];document.getElementById('cAuto').checked=false;}
document.querySelectorAll('button[data-v]').forEach(b=>b.onclick=()=>view(b.dataset.v));
cv.addEventListener('pointerdown',e=>{drag=true;lx=e.clientX;ly=e.clientY;cv.setPointerCapture(e.pointerId);document.getElementById('cAuto').checked=false;cv.style.cursor='grabbing';});
cv.addEventListener('pointerup',e=>{drag=false;cv.style.cursor='grab';});
cv.addEventListener('pointermove',e=>{if(!drag)return;yaw+=(e.clientX-lx)*0.01;pitch+=(e.clientY-ly)*0.01;pitch=Math.max(-1.55,Math.min(1.55,pitch));lx=e.clientX;ly=e.clientY;});
cv.addEventListener('wheel',e=>{e.preventDefault();zoom*=Math.exp(-e.deltaY*0.001);zoom=Math.max(0.4,Math.min(3,zoom));},{passive:false});
let pinch=0;cv.addEventListener('touchmove',e=>{if(e.touches.length==2){const d=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);if(pinch)zoom*=d/pinch;zoom=Math.max(0.4,Math.min(3,zoom));pinch=d;e.preventDefault();}},{passive:false});
cv.addEventListener('touchend',()=>pinch=0);

const W=cv.width,H=cv.height;
const img=ctx.createImageData(W,H),buf32=new Uint32Array(img.data.buffer),zbuf=new Float32Array(W*H);
const L=(()=>{const v=[-0.45,0.55,-0.75];const l=Math.hypot(...v);return v.map(x=>x/l);})();
const BG=0xFFF7FAFB;
let __stop=false,__raf=0;
function render(){
 if(document.getElementById('cAuto').checked&&!drag)yaw+=0.006;
 buf32.fill(BG);zbuf.fill(1e9);
 const cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch);
 const exp=document.getElementById('cExp').checked;
 const parts=[{m:shell,off:[0,0,0]},{m:bolts,off:[0,0,0]}];
 if(document.getElementById('cBoard').checked){const o=[0,0,exp?10:0];parts.push({m:board,off:o},{m:screen,off:o},{m:glow,off:o},{m:eyes,off:o});}
 if(document.getElementById('cBoard').checked)parts.push({m:batt,off:[0,0,exp?17:0]});
 if(document.getElementById('cLid').checked)parts.push({m:lid,off:[0,0,exp?26:0]});
 const DD=420,SC=7.0*zoom;
 const sx=new Float32Array(3),syv=new Float32Array(3),sz=new Float32Array(3);
 for(const pt of parts){const m=pt.m,p=m.p,o=pt.off,col=m.col;
  for(let i=0;i<m.n;i++){
   const nx=m.nm[i*3],ny=m.nm[i*3+1],nz=m.nm[i*3+2];
   const x1=nx*cy+nz*sy,z1=-nx*sy+nz*cy;const y2=ny*cp-z1*sp,z2=ny*sp+z1*cp;
   if(z2>0)continue;
   const sh=m.emissive?1:Math.max(0,x1*L[0]+y2*L[1]+z2*L[2])*0.65+0.35;
   const b=i*9;
   for(let k=0;k<3;k++){const X=p[b+k*3]-center[0]+o[0],Y=p[b+k*3+1]-center[1]+o[1],Z=p[b+k*3+2]-center[2]+o[2];
    const xa=X*cy+Z*sy,za=-X*sy+Z*cy;const ya=Y*cp-za*sp,zb=Y*sp+za*cp;
    const s=SC*DD/(DD+zb);sx[k]=W/2+xa*s;syv[k]=H/2-ya*s;sz[k]=zb;}
   const r=Math.min(255,col[0]*sh)|0,g=Math.min(255,col[1]*sh)|0,bl=Math.min(255,col[2]*sh)|0;
   const packed=(0xFF000000|(bl<<16)|(g<<8)|r)>>>0;
   let minx=Math.max(0,Math.floor(Math.min(sx[0],sx[1],sx[2]))),maxx=Math.min(W-1,Math.ceil(Math.max(sx[0],sx[1],sx[2])));
   let miny=Math.max(0,Math.floor(Math.min(syv[0],syv[1],syv[2]))),maxy=Math.min(H-1,Math.ceil(Math.max(syv[0],syv[1],syv[2])));
   const x0=sx[0],y0=syv[0],x1_=sx[1],y1_=syv[1],x2=sx[2],y2_=syv[2];
   const area=(x1_-x0)*(y2_-y0)-(x2-x0)*(y1_-y0);if(Math.abs(area)<1e-6)continue;const ia=1/area;
   for(let y=miny;y<=maxy;y++){for(let x=minx;x<=maxx;x++){
     const px=x+0.5,py=y+0.5;
     const w1=((px-x0)*(y2_-y0)-(x2-x0)*(py-y0))*ia;const w2=((x1_-x0)*(py-y0)-(px-x0)*(y1_-y0))*ia;const w0=1-w1-w2;
     if(w0<-0.002||w1<-0.002||w2<-0.002)continue;
     const d=w0*sz[0]+w1*sz[1]+w2*sz[2];const idx=y*W+x;
     if(d<zbuf[idx]){zbuf[idx]=d;buf32[idx]=packed;}}}
  }}
 ctx.putImageData(img,0,0);
 if(!__stop)__raf=requestAnimationFrame(render);}
render();
return function(){__stop=true;cancelAnimationFrame(__raf);};
};
